package com.yeyamo_mobile.api.partner_service.infrastructure.persistence;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="artisan_profiles")public class ArtisanProfileEntity{public enum VerificationStatus{DRAFT,PENDING,VERIFIED,REJECTED,SUSPENDED}@Id@Column(name="partner_id")private UUID partnerId;@Column(name="display_name",nullable=false)private String displayName;@Column(columnDefinition="TEXT",nullable=false)private String story;@Column(name="craft_description",columnDefinition="TEXT",nullable=false)private String craftDescription;@Column(name="years_of_experience")private Integer yearsOfExperience;@Column(name="country_code",nullable=false,length=2)private String countryCode;@Column(name="admin_level_1_id")private String adminLevel1Id;@Column(name="city_id")private String cityId;@Column(name="locality_id")private String localityId;@ElementCollection(fetch=FetchType.EAGER)@CollectionTable(name="artisan_profile_languages",joinColumns=@JoinColumn(name="partner_id"))@Column(name="language_code")private Set<String>languages=new HashSet<>();@ManyToMany(fetch=FetchType.EAGER)@JoinTable(name="artisan_profile_specialties",joinColumns=@JoinColumn(name="partner_id"),inverseJoinColumns=@JoinColumn(name="specialty_id"))private Set<ArtisanSpecialtyEntity>specialties=new HashSet<>();@Column(name="accepts_custom_orders",nullable=false)private boolean acceptsCustomOrders;@Column(name="international_shipping",nullable=false)private boolean internationalShipping;@Enumerated(EnumType.STRING)@Column(name="verification_status",nullable=false)private VerificationStatus verificationStatus;@Column(nullable=false)private boolean featured;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected ArtisanProfileEntity(){}public static ArtisanProfileEntity create(UUID partner,String name,String story,String craft,Integer years,String country,String a1,String city,String locality,Set<String>languages,Set<ArtisanSpecialtyEntity>specialties,boolean custom,boolean shipping){ArtisanProfileEntity p=new ArtisanProfileEntity();p.partnerId=partner;p.displayName=name;p.story=story;p.craftDescription=craft;p.yearsOfExperience=years;p.countryCode=country;p.adminLevel1Id=a1;p.cityId=city;p.localityId=locality;p.languages=languages;p.specialties=specialties;p.acceptsCustomOrders=custom;p.internationalShipping=shipping;p.verificationStatus=VerificationStatus.DRAFT;p.createdAt=Instant.now();p.updatedAt=p.createdAt;return p;}public void update(String name,String story,String craft,Integer years,String country,String a1,String city,String locality,Set<String>languages,Set<ArtisanSpecialtyEntity>specialties,boolean custom,boolean shipping){displayName=name;this.story=story;craftDescription=craft;yearsOfExperience=years;countryCode=country;adminLevel1Id=a1;cityId=city;localityId=locality;this.languages=languages;this.specialties=specialties;acceptsCustomOrders=custom;internationalShipping=shipping;if(verificationStatus==VerificationStatus.REJECTED)verificationStatus=VerificationStatus.DRAFT;updatedAt=Instant.now();}public void verification(VerificationStatus value){verificationStatus=value;updatedAt=Instant.now();}public UUID getPartnerId(){return partnerId;}public String getDisplayName(){return displayName;}public String getStory(){return story;}public String getCraftDescription(){return craftDescription;}public Integer getYearsOfExperience(){return yearsOfExperience;}public String getCountryCode(){return countryCode;}public String getAdminLevel1Id(){return adminLevel1Id;}public String getCityId(){return cityId;}public String getLocalityId(){return localityId;}public Set<String>getLanguages(){return Set.copyOf(languages);}public Set<ArtisanSpecialtyEntity>getSpecialties(){return Set.copyOf(specialties);}public boolean isAcceptsCustomOrders(){return acceptsCustomOrders;}public boolean isInternationalShipping(){return internationalShipping;}public VerificationStatus getVerificationStatus(){return verificationStatus;}public boolean isFeatured(){return featured;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
